class Solution {
  public long finishTime(int n, int[][] edges, int[] baseTime) {
    int[] head = new int[n], next = new int[n - 1], to = new int[n - 1];
    java.util.Arrays.fill(head, -1);
    for (int i = 0; i < n - 1; i++) {
      to[i] = edges[i][1];
      next[i] = head[edges[i][0]];
      head[edges[i][0]] = i;
    }
    int[] order = new int[n];
    int qh = 0, qt = 0;
    order[qt++] = 0;
    while (qh < qt) {
      int u = order[qh++];
      for (int e = head[u]; e >= 0; e = next[e]) order[qt++] = to[e];
    }
    long[] finish = new long[n];
    for (int idx = n - 1; idx >= 0; idx--) {
      int u = order[idx];
      if (head[u] < 0) {
        finish[u] = baseTime[u];
        continue;
      }
      long earliest = Long.MAX_VALUE, latest = Long.MIN_VALUE;
      for (int e = head[u]; e >= 0; e = next[e]) {
        earliest = Math.min(earliest, finish[to[e]]);
        latest = Math.max(latest, finish[to[e]]);
      }
      finish[u] = latest + (latest - earliest) + baseTime[u];
    }
    return finish[0];
  }
}
